// Parsea el JSON (HTTP Request lo entrega como string en .data o .body)
// y devuelve cada servicio como un item independiente
const input = $input.item.json;
let parsed;

// Probar varias formas en que n8n entrega el body
if (typeof input === 'string') {
  parsed = JSON.parse(input);
} else if (typeof input.data === 'string') {
  parsed = JSON.parse(input.data);
} else if (typeof input.body === 'string') {
  parsed = JSON.parse(input.body);
} else if (input.servicios) {
  parsed = input;
} else if (input.data && input.data.servicios) {
  parsed = input.data;
} else if (input.body && input.body.servicios) {
  parsed = input.body;
} else {
  throw new Error('No se pudo parsear el JSON. Estructura recibida: ' + JSON.stringify(Object.keys(input)));
}

if (!Array.isArray(parsed.servicios)) {
  throw new Error('No se encontro array "servicios" en el JSON. Keys disponibles: ' + JSON.stringify(Object.keys(parsed)));
}

return parsed.servicios.map(s => ({ json: s }));

// Construye el texto que sera embebido (concatena los campos relevantes)
const item = $input.item.json;
const entregables = (item.entregables || []).join('. ');
const casos = (item.casos_uso || []).join('. ');
const prereqs = (item.prerequisitos || []).join('. ');

const textoEmbedding = [
  item.nombre,
  item.descripcion_corta,
  item.descripcion_larga,
  `Precio setup: ${item.precio_setup || 'no aplica'}`,
  `Precio recurrente: ${item.precio_recurrente || 'no aplica'}`,
  `Tiempo entrega: ${item.tiempo_entrega || 'no aplica'}`,
  `Entregables: ${entregables}`,
  `Casos de uso: ${casos}`,
  `Prerequisitos: ${prereqs}`
].filter(Boolean).join('\n');

return {
  ...item,
  texto_embedding: textoEmbedding
};

// Construye el SQL INSERT completo con valores ya escapados (evita el bug de queryReplacement con comas en el embedding)
const servicio = $('Construir texto a embedear').item.json;
const embeddingResp = $input.item.json;
const embedding = embeddingResp.data?.[0]?.embedding;

if (!embedding) {
  throw new Error(`No se obtuvo embedding para ${servicio.slug}`);
}

function escString(s) {
  if (s === null || s === undefined) return 'NULL';
  return "'" + String(s).replace(/'/g, "''") + "'";
}

function escArray(arr) {
  if (!arr || !arr.length) return "ARRAY[]::text[]";
  return 'ARRAY[' + arr.map(escString).join(',') + ']::text[]';
}

const embedLiteral = "'[" + embedding.join(',') + "]'::vector";

const sql = `INSERT INTO kb_servicios (slug, categoria, nombre, descripcion_corta, descripcion_larga, precio_setup, precio_recurrente, tiempo_entrega, entregables, casos_uso, prerequisitos, embedding, updated_at)
VALUES (
  ${escString(servicio.slug)},
  ${escString(servicio.categoria)},
  ${escString(servicio.nombre)},
  ${escString(servicio.descripcion_corta)},
  ${escString(servicio.descripcion_larga)},
  ${escString(servicio.precio_setup)},
  ${escString(servicio.precio_recurrente)},
  ${escString(servicio.tiempo_entrega)},
  ${escArray(servicio.entregables)},
  ${escArray(servicio.casos_uso)},
  ${escArray(servicio.prerequisitos)},
  ${embedLiteral},
  NOW()
)
ON CONFLICT (slug) DO UPDATE SET
  categoria = EXCLUDED.categoria,
  nombre = EXCLUDED.nombre,
  descripcion_corta = EXCLUDED.descripcion_corta,
  descripcion_larga = EXCLUDED.descripcion_larga,
  precio_setup = EXCLUDED.precio_setup,
  precio_recurrente = EXCLUDED.precio_recurrente,
  tiempo_entrega = EXCLUDED.tiempo_entrega,
  entregables = EXCLUDED.entregables,
  casos_uso = EXCLUDED.casos_uso,
  prerequisitos = EXCLUDED.prerequisitos,
  embedding = EXCLUDED.embedding,
  updated_at = NOW()
RETURNING id, slug, nombre;`;

return { sql, slug: servicio.slug };
